<script setup>
import {ref} from 'vue'
import {api,errorText} from '../auth/api.js'
import {states,reasons,date,validateFiles} from '../property/property.js'
const props=defineProps({report:Object,admin:Boolean});const emit=defineEmits(['updated']);const busy=ref(false),error=ref('')
async function attach(event){const file=event.target.files[0];event.target.value='';if(!file)return;busy.value=true;error.value='';try{validateFiles([file],true);const data=new FormData();data.append('file',file);emit('updated',await api('/reports/'+props.report.id+'/attachments',{method:'POST',body:data}))}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function download(file){busy.value=true;error.value='';let url;try{const blob=await api(file.url.replace(/^\/api\/v1/,''),{responseType:'blob'});url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='bang-chung-'+file.id+({ 'image/png':'.png','image/jpeg':'.jpg','application/pdf':'.pdf' }[file.mimeType]||'');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><section class="sp-panel"><h2>{{reasons[report.reasonCode]||report.reasonCode}}</h2><p class="sp-muted">Mã báo cáo: {{report.id}} · {{date(report.createdAt)}}</p><span class="sp-tag">{{states[report.status]}}</span><p class="sp-pre">{{report.description}}</p><p v-if="report.contactEmail">Email liên hệ: {{report.contactEmail}}</p><p v-if="report.resolutionNote" class="sp-pre">Kết quả xử lý: {{report.resolutionNote}} · {{date(report.resolvedAt)}}</p><h3>Bằng chứng</h3><p v-if="error" role="alert" class="sp-error">{{error}}</p><div class="sp-row"><button v-for="(file,index) in report.attachments" :key="file.id" :disabled="busy" @click="download(file)">Tải tệp {{index+1}} · {{file.mimeType}} · {{Math.ceil(file.byteSize/1024)}} KB</button><p v-if="!report.attachments.length" class="sp-muted">Chưa có tệp đính kèm.</p></div><label v-if="!admin&&!['RESOLVED','REJECTED'].includes(report.status)" class="sp-label" style="margin-top:16px">Thêm bằng chứng (tối đa 10 tệp, 10 MB/tệp)<input type="file" accept="image/jpeg,image/png,application/pdf" :disabled="busy||report.attachments.length>=10" @change="attach"></label><slot /></section></template>